def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=0]
    cols=Counter(x[2] for x in cells)
    if len(cols)<2: return [row[:] for row in g]
    def bbox(col):
        rs=[r for r,c,v in cells if v==col]; cs=[c for r,c,v in cells if v==col]
        return (min(rs),max(rs),min(cs),max(cs))
    a,b=list(cols)
    ba,bb=bbox(a),bbox(b)
    if ba[0]<=bb[0] and ba[1]>=bb[1] and ba[2]<=bb[2] and ba[3]>=bb[3]:
        ob,(ocol),ib,icol=ba,a,bb,b
    else:
        ob,ocol,ib,icol=bb,b,ba,a
    r0,r1,c0,c1_=ob; ir0,ir1,ic0,ic1_=ib
    t=min(ir0-r0, r1-ir1, ic0-c0, c1_-ic1_)
    out=[row[:] for row in g]
    for r in range(max(0,r0-t), min(h,r1+t+1)):
        for c in range(max(0,c0-t), min(w,c1_+t+1)):
            if out[r][c]==0: out[r][c]=icol
    return out
